<script setup lang="ts">import {ref,onMounted} from 'vue';import {api} from '../../api';import {t} from '../../locales';import '../../styles/app.scss';const names=['重要新闻快讯','新交易点位','点位状态更新','系统通知'];const switches=ref<boolean[]>([]);onMounted(async()=>switches.value=[...(await api.notifications())]);async function toggle(i:number){const old=switches.value[i];switches.value[i]=!old;try{await api.saveNotifications(switches.value)}catch{switches.value[i]=old;uni.showToast({title:t('保存失败'),icon:'none'})}}</script>
<template><view class="notifications-page"><view class="notifications-nav"><text @click="uni.navigateBack()">‹</text><text>{{t('消息通知设置')}}</text></view><view class="notification-list"><view v-for="(name,i) in names" :key="name" class="notification-row"><view><text class="notification-icon" :class="`icon-${i}`">{{['▤','♧','⌁','⚙'][i]}}</text><text>{{t(name)}}</text></view><switch :checked="switches[i]" color="#2563EB" @change="toggle(i)"/></view><view class="notification-help"><text>ⓘ</text><text>{{t('开启后将通过系统推送通知送达')}}</text></view></view></view></template><style scoped>.notifications-page{min-height:100vh;background:#fff;color:var(--cf-text)}.notifications-nav{display:flex;align-items:center;gap:20rpx;height:78rpx;padding:0 28rpx;border-bottom:1rpx solid var(--cf-line);font-size:24rpx;font-weight:800}.notifications-nav text:first-child{font-size:41rpx;font-weight:400}.notification-list{padding:25rpx 28rpx}.notification-row{display:flex;align-items:center;justify-content:space-between;min-height:76rpx}.notification-row>view{display:flex;align-items:center;gap:16rpx;font-size:21rpx;font-weight:700}.notification-icon{display:grid;place-items:center;width:40rpx;height:40rpx;border-radius:10rpx;background:#EFF6FF;color:#2563EB;font-size:25rpx}.icon-1{background:#FFFBEB;color:#F59E0B}.icon-2{background:#ECFDF5;color:#10B981}.icon-3{background:#F1F5F9;color:#64748B}.notification-row switch{transform:scale(.7);transform-origin:right center}.notification-help{display:flex;align-items:center;gap:9rpx;margin-top:18rpx;padding-top:18rpx;border-top:1rpx solid var(--cf-line);color:var(--cf-soft);font-size:18rpx}</style>
<style scoped>.notifications-nav{height:86rpx;font-size:28rpx}.notification-row{min-height:88rpx}.notification-row>view{font-size:26rpx}.notification-icon{width:44rpx;height:44rpx;font-size:28rpx}.notification-help{font-size:22rpx}</style>
